export class AddressForm extends HTMLElement {
  constructor() {
    super();
  }

  static get observedAttributes() {
    return ["address"];
  }

  connectedCallback() {
    this.setForm();
  }

  private setForm() {
    const form = this.querySelector("form");
    if (!form) return;
    const countrySelector = form.querySelector(
      "[js-country-select]",
    ) as HTMLSelectElement;
    const provinceSelector = form.querySelector(
      "[js-province-select]",
    ) as HTMLSelectElement;
    if (countrySelector && provinceSelector) {
      this.setSelectedOption(countrySelector);
      this.setProvinceSelector(countrySelector, provinceSelector);
      countrySelector.addEventListener("change", () => {
        this.setProvinceSelector(countrySelector, provinceSelector);
      });
    }
  }

  private setSelectedOption(selector: HTMLSelectElement) {
    for (const option of selector.options) {
      if (option.value === selector.dataset.default) {
        selector.selectedIndex = option.index;
        break;
      }
    }
  }

  private getProvinces(select: HTMLSelectElement) {
    const selectedOption = select.options[select.selectedIndex];
    const provinces = JSON.parse(selectedOption.dataset.provinces || "[]");
    return provinces;
  }

  private setProvinceSelector(
    countrySelector: HTMLSelectElement,
    provinceSelector: HTMLSelectElement,
  ) {
    const provinces = this.getProvinces(countrySelector);
    provinceSelector.options.length = 0;
    if (provinces.length === 0) {
      if (provinceSelector.parentElement) {
        provinceSelector.parentElement.classList.add("hide");
      }
    } else {
      if (provinceSelector.parentElement) {
        provinceSelector.parentElement.classList.remove("hide");
      }
      const selectedProvince = provinceSelector.dataset.default;
      provinces.forEach((province: string[]) => {
        const optionElement = document.createElement("option");
        optionElement.textContent = province[0];
        optionElement.value = province[0];
        if (selectedProvince === province[0]) {
          optionElement.selected = true;
        }
        provinceSelector.appendChild(optionElement);
      });
    }
  }
}

customElements.define("uwp-address-form", AddressForm);
